"""

import json
import unittest
from unittest.mock import Mock

from gabbi import case
from gabbi import handlers
from gabbi import suitemaker


class ComprehensiveTest(unittest.TestCase):
    """Comprehensive test for the numeric regex fix."""

    def setUp(self):
        super().setUp()
        self.test_class = case.HTTPTestCase
        self.test = suitemaker.TestBuilder('mytest', (self.test_class,),
                                           {'test_data': {}})

    def test_various_numeric_types_with_regex(self):
        """Test various numeric types with different regex patterns."""
        handler = handlers.JSONResponseHandler(self.test_class)

        test_cases = [
            # (value, pattern, should_match)
            (42, r'^\d+$', True),           # integer matching digit pattern
            (42, r'^abc', False),           # integer not matching pattern
            (-5, r'^-\d+$', True),          # negative integer
            (0, r'^\d+$', True),            # zero
            (3.14, r'^\d+\.\d+$', True),    # positive float
            (-2.5, r'^-\d+\.\d+$', True),   # negative float
            (100.0, r'^\d+\.0*$', True),    # float ending in zeros
            (1e6, r'^\d+\.?\d*e\d+$', True), # scientific notation (will be converted to string)
        ]

        for i, (value, pattern, should_match) in enumerate(test_cases):
            with self.subTest(value=value, pattern=pattern, should_match=should_match):
                self.test.test_data = {'response_json_paths': {
                    f'$.value{i}': f'/{pattern}/',
                }}
                self.test.json_data = {f'value{i}': value}
                self.test.content_type = "application/json"

                test_instance = self.test('test_request')
                if should_match:
                    # Should pass without exception
                    handler(test_instance)
                else:
                    # Should fail with AssertionError
                    with self.assertRaises(AssertionError):
                        handler(test_instance)

    def test_boolean_and_none_values(self):
        """Test boolean and None values with regex."""
        handler = handlers.JSONResponseHandler(self.test_class)

        # Boolean values
        self.test.test_data = {'response_json_paths': {
            '$.flag': '/^(True|False)$/',
        }}
        self.test.json_data = {'flag': True}
        self.test.content_type = "application/json"

        test_instance = self.test('test_request')
        handler(test_instance)  # Should work: str(True) = 'True'

        # None value
        self.test.test_data = {'response_json_paths': {
            '$.empty': '/None/',
        }}
        self.test.json_data = {'empty': None}

        test_instance = self.test('test_request')
        handler(test_instance)  # Should work: str(None) = 'None'

    def test_complex_numbers_and_other_types(self):
        """Test that complex objects are handled reasonably."""
        handler = handlers.JSONResponseHandler(self.test_class)

        # Lists (these would normally be handled differently, but testing string conversion)
        self.test.test_data = {'response_json_paths': {
            '$.data': '/\\[\\d+, \\d+\\]/',
        }}
        self.test.json_data = {'data': [1, 2]}
        self.test.content_type = "application/json"

        test_instance = self.test('test_request')
        handler(test_instance)  # Should work: str([1, 2]) = '[1, 2]'

    def test_mixed_string_and_numeric_in_same_test(self):
        """Test that mixing strings and numbers in the same test works."""
        handler = handlers.JSONResponseHandler(self.test_class)

        self.test.test_data = {'response_json_paths': {
            '$.name': '/^Alice/',      # string value
            '$.age': '/^\\d+$/',       # numeric value
            '$.score': '/^\\d+\\.\\d+$/',  # float value
        }}
        self.test.json_data = {
            'name': 'Alice Smith',
            'age': 25,
            'score': 95.5
        }
        self.test.content_type = "application/json"

        test_instance = self.test('test_request')
        handler(test_instance)  # Should work for all three

    def test_exact_equality_still_works(self):
