def _register_responses(self):
    """Lazyly register default responses for all status codes"""
    # Lazy register a response for each status code
    for status in http.HTTPStatus:
        # Certain HTTP status codes must not have a response body according to HTTP standards:
        # - 1xx (Informational): Provisional responses, no body
        # - 204 No Content: Must not have a body
        # - 304 Not Modified: Must not have a body (used for caching)
        if status.value in (204, 304) or 100 <= status.value < 200:
            # These responses must not have content/body
            response = {
                "description": status.phrase,
            }
        else:
            # All other status codes can have error response bodies
            response = {
                "description": status.phrase,
                "schema": self.ERROR_SCHEMA,
            }
        prepare_response(response, self.spec, DEFAULT_RESPONSE_CONTENT_TYPE)
        self.spec.components.response(status.name, response, lazy=True)

    # Also lazy register a default error response
    response = {
        "description": "Default error response",
        "schema": self.ERROR_SCHEMA,
    }
    prepare_response(response, self.spec, DEFAULT_RESPONSE_CONTENT_TYPE)
    self.spec.components.response("DEFAULT_ERROR", response, lazy=True)

