#!/usr/bin/env python3
"""
Comprehensive test to verify the fix for HTTP status codes that should not have response bodies.
"""

import json
import http
from flask import Flask
from flask_smorest import Api, Blueprint


def test_no_body_status_codes():
    """Test that status codes without bodies are correctly registered."""

    app = Flask(__name__)
    app.config.update({
        'API_TITLE': 'Test API',
        'API_VERSION': 'v1',
        'OPENAPI_VERSION': '3.0.2',
    })

    api = Api(app)

    # Force load all lazy components
    with app.app_context():
        # Trigger lazy loading
        for status in http.HTTPStatus:
            try:
                api.spec.components.response(status.name)
            except:
                pass

        spec_dict = api.spec.to_dict()
        components = spec_dict.get('components', {})
        responses = components.get('responses', {})

        # Status codes that should NOT have response bodies
        no_body_codes = []
        for status in http.HTTPStatus:
            if status.value in (204, 304) or 100 <= status.value < 200:
                no_body_codes.append(status.value)

        print(f"Status codes that should NOT have response bodies: {sorted(no_body_codes)}")

        # Check each one
        issues = []
        for status_code_name, response_def in responses.items():
            # Find the numeric status code
            status_value = None
            for status_enum in http.HTTPStatus:
                if status_enum.name == status_code_name:
                    status_value = status_enum.value
                    break

            if status_value is None:
                continue

            content = response_def.get('content', {})

            if status_value in no_body_codes:
                if content:
                    issues.append(f"❌ {status_value} ({status_code_name}) should not have content but has: {content}")
                else:
                    print(f"✅ {status_value} ({status_code_name}) correctly has no content")
            elif content:
                # Normal case - should have content
                print(f"ℹ️  {status_value} ({status_code_name}) correctly has content")

        return issues


def test_endpoint_references():
    """Test that endpoint references to no-body status codes work correctly."""

    app = Flask(__name__)
    app.config.update({
        'API_TITLE': 'Test API',
        'API_VERSION': 'v1', 
        'OPENAPI_VERSION': '3.0.2',
    })

    api = Api(app)

    # Create blueprint with ETag (which documents 304)
    blp = Blueprint('test', 'test', url_prefix='/test')

    @blp.route('/', methods=['GET'])
    @blp.etag
    def get_test():
        return {'message': 'Hello'}

    api.register_blueprint(blp)

    with app.app_context():
        spec_dict = api.spec.to_dict()
        paths = spec_dict.get('paths', {})

        issues = []
        for path, path_def in paths.items():
            for method, method_def in path_def.items():
                responses = method_def.get('responses', {})
                for status_code, response_def in responses.items():
                    if str(status_code) == '304':
                        if '$ref' in response_def:
                            ref_path = response_def['$ref']
                            if ref_path.startswith('#/components/responses/'):
                                ref_name = ref_path.split('/')[-1]
                                components = spec_dict.get('components', {})
                                global_responses = components.get('responses', {})
                                if ref_name in global_responses:
                                    actual_response = global_responses[ref_name]
