"""
Comprehensive final test covering all aspects of the adjoint method fix.
"""

import pennylane as qml
import numpy as np

def test_original_issue_fixed():
    """Test that the original issue from GitHub is fixed."""
    print("1. Testing original issue case...")

    dev = qml.device("default.qubit", wires=2)

    @qml.qnode(dev, diff_method="adjoint")
    def circuit():
        return qml.state()

    result = circuit()
    assert result.shape == (4,)
    print("   ✓ Original issue fixed!")

def test_all_global_measurements():
    """Test various global wire measurements."""
    print("2. Testing all global measurements...")

    dev = qml.device("default.qubit", wires=3)

    # Test state measurement
    @qml.qnode(dev, diff_method="adjoint")
    def circuit_state():
        return qml.state()

    result = circuit_state()
    assert result.shape == (8,)  # 2^3
    print("   ✓ qml.state() works")

    # Test probs measurement
    @qml.qnode(dev, diff_method="adjoint") 
    def circuit_probs():
        return qml.probs()

    result = circuit_probs()
    assert result.shape == (8,)  # 2^3
    assert abs(sum(result) - 1.0) < 1e-10  # probabilities sum to 1
    print("   ✓ qml.probs() works")

def test_local_measurements_still_work():
    """Test that local measurements still work (regression test)."""
    print("3. Testing local measurements still work...")

    dev = qml.device("default.qubit", wires=2)

    # Test expectation value
    @qml.qnode(dev, diff_method="adjoint")
    def circuit_expval():
        return qml.expval(qml.PauliZ(0))

    result = circuit_expval()
    assert isinstance(result, (float, np.float64))
    print("   ✓ qml.expval() works")

    # Test variance
    @qml.qnode(dev, diff_method="adjoint")
    def circuit_var():
        return qml.var(qml.PauliZ(0))

    result = circuit_var()
    assert isinstance(result, (float, np.float64))
    print("   ✓ qml.var() works")

def test_mixed_measurements():
    """Test circuits with both global and local measurements."""
    print("4. Testing mixed measurements...")

    dev = qml.device("default.qubit", wires=2)

    # Test multiple global measurements
    @qml.qnode(dev, diff_method="adjoint")
    def circuit_multiple_global():
        return qml.state(), qml.probs()

    result = circuit_multiple_global()
    assert isinstance(result, tuple)
    assert len(result) == 2
    assert result[0].shape == (4,)
    assert result[1].shape == (4,)
    print("   ✓ Multiple global measurements work")

    # Test global + local measurements (should fail gracefully)
    @qml.qnode(dev, diff_method="adjoint")
    def circuit_mixed():
        return qml.state(), qml.expval(qml.PauliZ(0))

    try:
        result = circuit_mixed()
        print("   ⚠ Mixed measurements work (unexpected but okay)")
    except Exception as e:
        print(f"   ✓ Mixed measurements correctly rejected: {type(e).__name__}")

def test_parameterized_circuits():
    """Test parameterized circuits with global measurements."""
    print("5. Testing parameterized circuits...")

    dev = qml.device("default.qubit", wires=2)

    @qml.qnode(dev, diff_method="adjoint")
    def circuit(x, y):
        qml.RX(x, wires=0)
        qml.RY(y, wires=1)
        return qml.state()

    x, y = 0.3, 0.7
    result = circuit(x, y)
    assert result.shape == (4,)
    # State should be normalized
    assert abs(np.linalg.norm(result) - 1.0) < 1e-10
    print("   ✓ Parameterized circuits work")

def test_different_wire_configurations():
    """Test different numbers of wires."""
    print("6. Testing different wire configurations...")

    for n_wires in [1, 2, 3, 4]:
        dev = qml.device("default.qubit", wires=n_wires)

        @qml.qnode(dev, diff_method="adjoint")
        def circuit():
            return qml.state()

        result = circuit()
        expected_shape = (2**n_wires,)
        assert result.shape == expected_shape, f"Failed for {n_wires} wires"
        print(f"   ✓ {n_wires} wires: shape {result.shape}")

if __name__ == "__main__":
    print("Running comprehensive final tests...\n")

    try:
        test_original_issue_fixed()
        test_all_global_measurements()
        test_local_measurements_still_work()
        test_mixed_measurements()
        test_parameterized_circuits()
        test_different_wire_configurations()

        print("\n🎉 ALL COMPREHENSIVE TESTS PASSED!")
        print("The adjoint method fix is working correctly.")

    except Exception as e:
        print(f"\n❌ TEST FAILED: {type(e).__name__}: {e}")
        import traceback
