        num_part = item_str[1:]
        # Check: positive integer (> 0) and no leading zeros
        if len(num_part) > 1:
            # Multi-digit numbers cannot start with 0
            return not num_part.startswith("0") and int(num_part) > 0
        else:
            # Single digit must be > 0
