import sys
sys.path.insert(0, '.')

from artifactory import quote_url

def test_comprehensive():
    """Comprehensive test of quote_url function"""

    test_cases = [
        # Basic case without port
        {
            "input": "https://example.com/artifactory/foo",
            "expected": "https://example.com/artifactory/foo",
            "description": "Basic URL without port"
        },
        # Case with port (the main issue)
        {
            "input": "https://example.com:80/artifactory/foo",
            "expected": "https://example.com:80/artifactory/foo",
            "description": "URL with explicit port 80"
        },
        # Case with different port
        {
            "input": "http://localhost:8081/artifactory/repo",
            "expected": "http://localhost:8081/artifactory/repo",
            "description": "HTTP URL with port 8081"
        },
        # Case with special characters that should be encoded
        {
            "input": "https://example.com:80/artifactory/foo/#1",
            "expected": "https://example.com:80/artifactory/foo/%231",
            "description": "URL with port and hash (should encode #)"
        },
        # Case with special characters and no port
        {
            "input": "https://example.com/artifactory/foo/#1",
            "expected": "https://example.com/artifactory/foo/%231",
            "description": "URL without port and hash (should encode #)"
        },
        # Case with question mark
        {
            "input": "https://example.com:80/artifactory/foo?param=value",
            "expected": "https://example.com:80/artifactory/foo%3Fparam=value",
            "description": "URL with port and query param (should encode ?)"
        }
    ]

    all_passed = True

    for i, test_case in enumerate(test_cases, 1):
        input_url = test_case["input"]
        expected_url = test_case["expected"]
        description = test_case["description"]

        actual_url = quote_url(input_url)

        print(f"Test {i}: {description}")
        print(f"  Input:    {input_url}")
        print(f"  Expected: {expected_url}")
        print(f"  Actual:   {actual_url}")

        if actual_url == expected_url:
            print("  ✅ PASS\n")
        else:
            print("  ❌ FAIL\n")
            all_passed = False

    return all_passed

if __name__ == "__main__":
    success = test_comprehensive()
    sys.exit(0 if success else 1)

