#!/usr/bin/env python3
"""
Test for the fix of misleading IndentationError with unconstrained item schemas.
This addresses the issue where schemas like {"items": {"unknown": "value"}} 
would cause IndentationError instead of properly handling unconstrained schemas.
"""

import fastjsonschema
import pytest


def test_unconstrained_items_schema_no_indentation_error():
    """Test that unconstrained items schemas don't cause IndentationError."""
    # This is the exact schema from the issue report
    schema = {
        "type": "object",
        "properties": {
            "a": {
                "type": "array",
                "items": {
                    "b": {
                        "type": "string"
                    }
                }
            }
        }
    }

    # This should not raise IndentationError
    validator = fastjsonschema.compile(schema)

    # Test that it works correctly
    # Should accept any array contents since items schema is unconstrained
    assert validator({"a": []}) == {"a": []}
    assert validator({"a": [{}]}) == {"a": [{}]}
    assert validator({"a": [{"b": "test"}]}) == {"a": [{"b": "test"}]}
    assert validator({"a": [{"b": 123}]}) == {"a": [{"b": 123}]}
    assert validator({"a": ["string", 123, None]}) == {"a": ["string", 123, None]}


def test_empty_items_schema():
    """Test that empty items schemas work correctly."""
    schema = {
        "type": "array",
        "items": {}
    }

    validator = fastjsonschema.compile(schema)

    # Should accept any array contents
    assert validator([]) == []
    assert validator([1, 2, 3]) == [1, 2, 3]
    assert validator(["a", "b"]) == ["a", "b"]
    assert validator([{}, []]) == [{}, []]


def test_unknown_properties_items_schema():
    """Test items schemas with only unknown properties."""
    schema = {
        "type": "array",
        "items": {
            "unknown_keyword": "value",
            "another_unknown": {"nested": "value"}
        }
    }

    validator = fastjsonschema.compile(schema)

    # Should accept any array contents
    assert validator([1, 2, 3]) == [1, 2, 3]


def test_nested_unconstrained_arrays():
    """Test nested arrays with unconstrained schemas."""
    schema = {
        "type": "object",
        "properties": {
            "matrix": {
                "type": "array",
                "items": {
                    "type": "array",
                    "items": {
                        "some_key": "some_value"
                    }
                }
            }
        }
    }

    validator = fastjsonschema.compile(schema)

    # Should work correctly
    result = validator({"matrix": [[1, 2], [3, 4]]})
    assert result == {"matrix": [[1, 2], [3, 4]]}


if __name__ == "__main__":
    test_unconstrained_items_schema_no_indentation_error()
    test_empty_items_schema()
    test_unknown_properties_items_schema()
    test_nested_unconstrained_arrays()
    print("All tests passed!")

