#!/usr/bin/env python3
"""
Test that validates the fix for the misleading IndentationError issue.

Issue: https://github.com/horejsek/python-fastjsonschema/issues/[issue-number]

Before the fix, this schema would cause:
IndentationError: expected an indented block (<string>, line 18)

After the fix, it compiles successfully and works correctly.
"""

import fastjsonschema


def test_issue_schema_compiles_without_indentation_error():
    """Test that the exact schema from the issue compiles without IndentationError."""
    schema = {
        "type": "object",
        "properties": {
            "a": {
                "type": "array",
                "items": {
                    "b": {
                        "type": "string"
                    }
                }
            }
        }
    }

    # This should not raise IndentationError
    validator = fastjsonschema.compile(schema)

    # Test that it validates correctly
    # The items schema {"b": {"type": "string"}} is unconstrained 
    # (missing root-level type), so it should accept any values

    # Valid cases
    assert validator({"a": []}) == {"a": []}
    assert validator({"a": [1, 2, 3]}) == {"a": [1, 2, 3]}
    assert validator({"a": [{"b": "test"}]}) == {"a": [{"b": "test"}]}
    assert validator({"a": [{"b": 123}]}) == {"a": [{"b": 123}]}  # Type mismatch ignored for unconstrained schema

    # Invalid case - array expected
    try:
        validator({"a": "not_an_array"})
        assert False, "Should have raised validation error"
    except fastjsonschema.JsonSchemaValueException:
        pass  # Expected


def test_code_generation_produces_valid_syntax():
    """Test that code generation produces syntactically valid Python code."""
    schema = {
        "type": "object",
        "properties": {
            "a": {
                "type": "array",
                "items": {
                    "b": {
                        "type": "string"
                    }
                }
            }
        }
    }

    # Generate code
    code = fastjsonschema.compile_to_code(schema)

    # Verify it's syntactically valid
    compile(code, '<generated>', 'exec')

    # Verify it contains pass statements to prevent empty loops
    assert 'pass' in code
    assert 'for data__a_x, data__a_item in enumerate(data__a):' in code
    assert 'pass' in code[code.find('for data__a_x, data__a_item in enumerate(data__a):'):]


if __name__ == "__main__":
    test_issue_schema_compiles_without_indentation_error()
    test_code_generation_produces_valid_syntax()
    print("✅ All tests passed! Issue is fixed.")

