        def get_pet_owner(pet_id, owner_id):
            return f"owner {owner_id} of pet {pet_id}"

        spec.path(view=get_pet_owner)
        paths = get_paths(spec)
        assert "/pet/{pet_id}/owner/{owner_id}" in paths

