"""

from rdflib import Graph

def test_exponent_notation():
    """Test various exponent notation formats."""
    test_cases = [
        # (description, turtle_content, expected_triples)
        ("Leading dot with single digit", "@prefix ex: <http://example.org/> .\nex:a ex:value .5e10 .", 1),
        ("Leading dot with multiple digits", "@prefix ex: <http://example.org/> .\nex:a ex:value .171e-11 .", 1),
        ("Leading dot with multiple digits positive exp", "@prefix ex: <http://example.org/> .\nex:a ex:value .123e+5 .", 1),
        ("Negative leading dot", "@prefix ex: <http://example.org/> .\nex:a ex:value -.456e-7 .", 1),
