        ("Integer with exponent", "@prefix ex: <http://example.org/> .\nex:a ex:value 123e-10 .", 1),
        ("Multiple values in one graph", "@prefix ex: <http://example.org/> .\nex:a ex:v1 .171e-11 ; ex:v2 .5e+2 ; ex:v3 1.23e-4 .", 3),
