#!/usr/bin/env python3

"""
Comprehensive test to verify the fix handles various edge cases
"""

import os
from unittest.mock import Mock
from dvc.command.diff import CmdDiff

def create_mock_args(**kwargs):
    """Create mock arguments for the diff command"""
    args = Mock()
    args.a_rev = kwargs.get('a_rev', 'HEAD')
    args.b_rev = kwargs.get('b_rev', None)
    args.show_json = kwargs.get('show_json', False)
    args.show_hash = kwargs.get('show_hash', False)
    args.show_md = kwargs.get('show_md', False)
    return args

def test_edge_cases():
    """Test various edge cases"""

    test_cases = [
        {
            "name": "Normal case",
            "diff": {
                "added": [{"path": "file1.txt", "hash": "abc123"}],
                "deleted": [{"path": "file2.txt", "hash": "def456"}],
                "modified": [{"path": "file3.txt", "hash": {"old": "old123", "new": "new456"}}]
            },
            "should_succeed": True
        },
        {
            "name": "None path case",
            "diff": {
                "added": [{"path": None, "hash": "abc123"}],
                "deleted": [{"path": "file2.txt", "hash": "def456"}],
                "modified": []
            },
            "should_succeed": True
        },
        {
            "name": "Mixed None and normal paths",
            "diff": {
                "added": [
                    {"path": "normal_file.txt", "hash": "abc123"},
                    {"path": None, "hash": "def456"}
                ],
                "deleted": [],
                "modified": [{"path": None, "hash": {"old": "old123", "new": "new456"}}]
            },
            "should_succeed": True
        },
        {
            "name": "Empty diff",
            "diff": {
                "added": [],
                "deleted": [],
                "modified": []
            },
            "should_succeed": True
        },
        {
            "name": "Directory paths (ending with os.sep)",
            "diff": {
                "added": [{"path": "dir" + os.sep, "hash": "abc123"}],
                "deleted": [{"path": "another_dir" + os.sep, "hash": "def456"}],
                "modified": [{"path": "mod_dir" + os.sep, "hash": {"old": "old123", "new": "new456"}}]
            },
            "should_succeed": True
        }
    ]

    results = []

    for test_case in test_cases:
        print(f"\n=== Testing: {test_case['name']} ===")

        args = create_mock_args()
        cmd = CmdDiff(args)
        cmd.repo = Mock()

        try:
            result = cmd._format(test_case['diff'])
            print("✓ Success")
            if test_case['name'] == "None path case":
                print("Output preview:", result.split('\n')[2] if len(result.split('\n')) > 2 else result[:100])
            results.append(True)
        except Exception as e:
            print(f"✗ Failed: {e}")
            import traceback
            traceback.print_exc()
            results.append(False)

    # Summary
    print(f"\n=== SUMMARY ===")
    passed = sum(results)
    total = len(results)
    print(f"Passed: {passed}/{total}")

    if passed == total:
        print("🎉 All tests passed!")
        return True
    else:
        print("❌ Some tests failed")
        return False

if __name__ == "__main__":
    test_edge_cases()

