def test_old_imports():
    """Test the old import style that worked in v6 but fails in v7."""
    print("Testing old middleware imports that should fail in v7...")

    try:
        from web3.middleware import construct_sign_and_send_raw_middleware
        print("✓ construct_sign_and_send_raw_middleware imported successfully")
    except ImportError as e:
