    try:
        from web3.middleware import pythonic_middleware
        print("✓ pythonic_middleware imported successfully")
    except ImportError as e:
        print(f"✗ Failed to import pythonic_middleware: {e}")

    try:
        from web3.middleware import geth_poa_middleware
        print("✓ geth_poa_middleware imported successfully")
    except ImportError as e:
        print(f"✗ Failed to import geth_poa_middleware: {e}")

def test_new_imports():
    """Test the new import style that should work in v7."""
    print("\nTesting new middleware imports that should work in v7...")

    try:
        from web3.middleware import SignAndSendRawMiddlewareBuilder
        print("✓ SignAndSendRawMiddlewareBuilder imported successfully")
    except ImportError as e:
        print(f"✗ Failed to import SignAndSendRawMiddlewareBuilder: {e}")

    try:
