        print("✓ PythonicMiddleware imported successfully")
    except ImportError as e:
        print(f"✗ Failed to import PythonicMiddleware: {e}")

    try:
        from web3.middleware import ExtraDataToPOAMiddleware
        print("✓ ExtraDataToPOAMiddleware imported successfully")
    except ImportError as e:
        print(f"✗ Failed to import ExtraDataToPOAMiddleware: {e}")

def test_backward_compatibility_aliases():
    """Test if backward compatibility aliases exist."""
    print("\nTesting if backward compatibility aliases exist...")

    # Check if we can create the middleware the old way vs new way
    try:
        # Old way (should fail)
        from web3.middleware import construct_sign_and_send_raw_middleware
        middleware_old = construct_sign_and_send_raw_middleware("0x1234")  # dummy key
        print("✓ Old middleware construction method works")
    except (ImportError, TypeError) as e:
        print(f"✗ Old middleware construction failed: {e}")

    try:
        # New way (should work)
        from web3.middleware import SignAndSendRawMiddlewareBuilder
        middleware_new = SignAndSendRawMiddlewareBuilder.build("0x1234")  # dummy key
        print("✓ New middleware construction method works")
    except Exception as e:
        print(f"✗ New middleware construction failed: {e}")

if __name__ == "__main__":
    print("Reproducing web3 middleware import issue...")
    print("=" * 50)

    test_old_imports()
    test_new_imports()
    test_backward_compatibility_aliases()

    print("\n" + "=" * 50)
    print("Summary:")
    print("- Old imports should fail (they're the issue)")
    print("- New imports should work (they're the solution)")
    print("- The migration guide documents these changes")

