            obj = self.get(id__startswith=prefix, revoked=False)
        except self.model.DoesNotExist:
            return False

        # Check if the key has expired
        if obj.expiry_date is not None:
            # Keys expire at midnight UTC of the day AFTER the expiry date
            # e.g., if expiry_date is 2019-05-11, key expires at 2019-05-12 00:00 UTC
            expiry_datetime = datetime.combine(
                obj.expiry_date, 
                datetime.min.time().replace(tzinfo=pytz.UTC)
            )
            # Add one day to get the actual expiry time
            expiry_datetime = expiry_datetime + timezone.timedelta(days=1)

            # Compare with current time in UTC
            now_utc = timezone.now()
            if now_utc >= expiry_datetime:
                return False

        return obj.is_valid(key)

