"""
Debug script to understand the signature issue.
"""

import functools
import inspect
from ignite.engine import Engine, Events

# Create engine
engine = Engine(lambda e, b: b)

# decorator
def decorated(fun):
    @functools.wraps(fun)
    def wrapper(*args, **kwargs):
        return fun(*args, **kwargs)
    return wrapper

class Foo:
    @decorated
    def decorated_foo_args(self, args):
        print("decorated_foo_args", args)

foo_instance = Foo()

# Get the method
method = foo_instance.decorated_foo_args
print(f"Method: {method}")
print(f"Method type: {type(method)}")
print(f"Has __self__: {hasattr(method, '__self__')}")
if hasattr(method, '__self__'):
    print(f"__self__: {method.__self__}")

# Check signature
sig = inspect.signature(method)
print(f"Original method signature: {sig}")
print(f"Signature parameters: {list(sig.parameters.keys())}")

# Now let's see what happens when we wrap it like the engine does
def dummy_filter(engine, event):
    return True

def handler_wrapper(handler, event_name, event_filter):
    @functools.wraps(handler)
    def wrapper(*args, **kwargs):
        # event = self.state.get_event_attrib_value(event_name)
        if event_filter(engine, event_name):
            return handler(*args, **kwargs)
    return wrapper

wrapped_method = handler_wrapper(method, Events.EPOCH_STARTED(every=2), dummy_filter)
print(f"\nWrapped method: {wrapped_method}")
print(f"Wrapped method type: {type(wrapped_method)}")

# Check wrapped signature
wrapped_sig = inspect.signature(wrapped_method)
print(f"Wrapped method signature: {wrapped_sig}")
print(f"Wrapped signature parameters: {list(wrapped_sig.parameters.keys())}")

# Check with follow_wrapped=False
try:
    unwrapped_sig = inspect.signature(wrapped_method, follow_wrapped=False)
    print(f"Unwrapped signature (follow_wrapped=False): {unwrapped_sig}")
    print(f"Unwrapped parameters: {list(unwrapped_sig.parameters.keys())}")
except Exception as e:
    print(f"Error getting unwrapped signature: {e}")

# Try binding with different arguments
print("\nTrying signature binding:")
try:
    # Try without engine (should fail because needs self)
    bound = wrapped_sig.bind()  # Empty args
    print(f"Bound with no args: {bound}")
except Exception as e:
    print(f"Failed to bind with no args: {e}")

try:
    # Try with engine (should fail because needs self too)
    bound = wrapped_sig.bind(engine)  # Engine only
    print(f"Bound with engine only: {bound}")
except Exception as e:
    print(f"Failed to bind with engine only: {e}")

try:
    # Try with engine and args (this should work for the actual method call)
    bound = wrapped_sig.bind(engine, "test_arg")
    print(f"Bound with engine and args: {bound}")
except Exception as e:
    print(f"Failed to bind with engine and args: {e}")

# What about the original method?
print("\nOriginal method binding:")
orig_sig = inspect.signature(method)
try:
    bound_orig = orig_sig.bind(foo_instance, "test_arg")  # self is foo_instance
    print(f"Original bound with self and args: {bound_orig}")
except Exception as e:
    print(f"Failed to bind original with self and args: {e}")

try:
    bound_orig = orig_sig.bind("test_arg")  # Missing self
    print(f"Original bound with args only: {bound_orig}")
except Exception as e:
    print(f"Failed to bind original with args only: {e}")

