        ("decorated method with args and filter", lambda: engine.add_event_handler(Events.EPOCH_STARTED(every=2), foo_instance.decorated_foo_args)),  # THE FIX
    ]

    success_count = 0
    total_count = len(test_cases)

    for name, test_func in test_cases:
        try:
            test_func()
            print(f"✓ {name}")
            success_count += 1
        except Exception as e:
            print(f"✗ {name}: {e}")

    print(f"\nResult: {success_count}/{total_count} tests passed")
    return success_count == total_count

def test_edge_cases():
    """Test edge cases to ensure robustness."""
    print("\n=== Testing Edge Cases ===")

    engine = Engine(lambda e, b: b)

    # Test with multiple decorators
    def decorator1(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper

    def decorator2(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper

    class TestClass:
        @decorator1
        @decorator2
        def doubly_decorated_method(self, arg):
            return f"doubly_decorated: {arg}"

    instance = TestClass()

    try:
        # This should work with our fix
        engine.add_event_handler(Events.EPOCH_STARTED(every=2), instance.doubly_decorated_method)
        print("✓ Doubly decorated method with filter")
    except Exception as e:
        print(f"✗ Doubly decorated method with filter: {e}")
        return False

    # Test with kwargs
    class KwargsClass:
        @decorator1
        def method_with_kwargs(self, engine_arg, optional=None):
            return f"method_with_kwargs: {engine_arg}, {optional}"

    kwargs_instance = KwargsClass()

    try:
        engine.add_event_handler(Events.EPOCH_STARTED(every=2), kwargs_instance.method_with_kwargs)
        print("✓ Method with kwargs and filter")
    except Exception as e:
        print(f"✗ Method with kwargs and filter: {e}")
        return False

    return True

def test_execution():
    """Test that handlers actually execute correctly."""
    print("\n=== Testing Execution ===")

    engine = Engine(lambda e, b: b)
    results = []

    def decorated(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            results.append(result)
            return result
        return wrapper

    class HandlerClass:
        @decorated
        def handle_epoch(self, engine):
            return f"handled by {type(self).__name__}"

    instance = HandlerClass()

    # This was the failing case
    engine.add_event_handler(Events.EPOCH_STARTED(every=1), instance.handle_epoch)

    try:
        engine.run([1, 2], max_epochs=1)
        if results:
            print("✓ Handler executed correctly")
            print(f"  Results: {results}")
            return True
        else:
            print("✗ Handler did not execute")
            return False
    except Exception as e:
        print(f"✗ Handler execution failed: {e}")
        return False

if __name__ == "__main__":
    print("Running comprehensive tests...\n")

    success = True
    success &= test_all_combinations()
    success &= test_edge_cases() 
    success &= test_execution()

    if success:
        print("\n🎉 All tests passed!")
    else:
        print("\n❌ Some tests failed!")
        exit(1)

