"""
Test to verify the specific fix for decorated bound methods with filtered events.
This test can be added to the official test suite.
"""

import functools
import pytest
from ignite.engine import Engine, Events


def test_decorated_bound_method_with_filtered_event():
    """Test that decorated bound methods can be registered with filtered events."""

    # Create engine
    engine = Engine(lambda e, b: b)

    # decorator
    def decorated(fun):
        @functools.wraps(fun)
        def wrapper(*args, **kwargs):
            return fun(*args, **kwargs)
        return wrapper

    class TestHandler:
        def __init__(self):
            self.call_count = 0

        @decorated
        def handle_event(self, engine_arg):
            """Handler that takes engine as argument."""
            self.call_count += 1
            return f"handled_{self.call_count}"

    # Create handler instance
    handler = TestHandler()

    # This was the failing case before the fix
    # Should not raise ValueError about missing 'self' parameter
    engine.add_event_handler(Events.EPOCH_STARTED(every=2), handler.handle_event)

    # Verify the handler actually works
    engine.run([1, 2, 3], max_epochs=4)  # Should trigger on epochs 2 and 4

    # Should have been called twice (epoch 2 and 4)
    assert handler.call_count == 2


def test_multiple_decorators_bound_method_with_filtered_event():
    """Test that multiply decorated bound methods work with filtered events."""

    engine = Engine(lambda e, b: b)

    def decorator1(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper

    def decorator2(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper

    class TestHandler:
        @decorator1
        @decorator2
        def handle_event(self, engine_arg):
            return "handled"

    handler = TestHandler()

    # Should not raise any errors
    engine.add_event_handler(Events.ITERATION_STARTED(every=2), handler.handle_event)


def test_decorated_bound_method_various_signatures():
    """Test decorated bound methods with various method signatures."""

    engine = Engine(lambda e, b: b)

    def decorated(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper

    class TestHandler:
        @decorated
        def no_args_method(self):
            return "no_args"

        @decorated 
        def one_arg_method(self, arg):
            return f"one_arg: {arg}"

        @decorated
        def multi_arg_method(self, arg1, arg2, kwarg1=None):
            return f"multi: {arg1}, {arg2}, {kwarg1}"

    handler = TestHandler()

    # All these should work without signature errors
    engine.add_event_handler(Events.EPOCH_STARTED(every=2), handler.no_args_method)
    engine.add_event_handler(Events.EPOCH_STARTED(every=3), handler.one_arg_method)
    engine.add_event_handler(Events.EPOCH_STARTED(every=4), handler.multi_arg_method, "arg1", "arg2", kwarg1="kwarg1")


if __name__ == "__main__":
    test_decorated_bound_method_with_filtered_event()
    test_multiple_decorators_bound_method_with_filtered_event()
    test_decorated_bound_method_various_signatures()
    print("All fix verification tests passed!")

