#!/usr/bin/env python3

"""Test the fixed TSQL behavior."""

import sqlglot
from sqlglot import exp

def test_parsing_behavior():
    print("=== Testing || parsing with TSQL dialect ===")

    # Test parsing || with TSQL (should now treat as OR)
    sql_with_dpipe = "SELECT 'Hello' || 'World'"

    try:
        parsed_tsql = sqlglot.parse_one(sql_with_dpipe, dialect="tsql")
        print(f"TSQL parsed: {parsed_tsql}")
        print(f"TSQL AST type: {type(parsed_tsql.expressions[0]).__name__}")

        # Check if it's OR now
        if isinstance(parsed_tsql.expressions[0], exp.Or):
            print("✅ GOOD: || now parsed as OR in TSQL")
        elif hasattr(parsed_tsql.expressions[0], 'this') and isinstance(parsed_tsql.expressions[0].this, exp.Or):
            print("✅ GOOD: || now parsed as OR in TSQL (nested)")  
        else:
            print("❌ ISSUE: || still not parsed as OR")

    except Exception as e:
        print(f"TSQL parsing error: {e}")

    print()

def test_concat_generation():
    print("=== Testing Concat expression generation ===")

    # Create explicit Concat expression
    concat_expr = exp.Concat(expressions=[
        exp.Literal.string('Hello'),
        exp.Literal.string(' '),
        exp.Literal.string('World')
    ])
    select_expr = exp.Select(expressions=[concat_expr])

    print(f"Concat expression: {select_expr}")

    try:
        tsql_output = select_expr.sql(dialect="tsql")
        print(f"TSQL output: {tsql_output}")

        if "+" in tsql_output and "CONCAT" not in tsql_output:
            print("✅ GOOD: Concat now generates + in TSQL")
        else:
            print("❌ ISSUE: Concat still not generating +")

    except Exception as e:
        print(f"TSQL generation error: {e}")

    print()

def test_existing_tests():
    print("=== Testing existing functionality ===")

    # Test that + still works
    plus_sql = "SELECT 'Hello' + 'World'"
    try:
        parsed = sqlglot.parse_one(plus_sql, dialect="tsql")
        output = parsed.sql(dialect="tsql")
        print(f"+ parsing/generation: {plus_sql} → {output}")
        if output == plus_sql:
            print("✅ GOOD: + operations unchanged")
        else:
            print("❌ ISSUE: + operations changed unexpectedly")
    except Exception as e:
        print(f"+ test error: {e}")

    print()

if __name__ == "__main__":
    test_parsing_behavior()
    test_concat_generation() 
    test_existing_tests()

