#!/usr/bin/env python3
"""Test that could be added to the official test suite."""

import configparser
import tempfile
import os

# This would be added to tests/unit/test_options_config.py
def test_load_config_auto_discovered_file_disappears_gracefully(tmpdir):
    """Test that auto-discovered config files that disappear are handled gracefully.

    This addresses the GitHub Actions issue where config files found during
    auto-discovery might not exist when actually read, causing false errors.
    """
    with tmpdir.as_cwd():
        # Create a config file temporarily
        tmpdir.join(".flake8").write("[flake8]\nmax-line-length = 88\n")

        # Simulate the race condition: file exists during discovery but not during reading
        # We do this by mocking _find_config_file to return a path that will be deleted

        from flake8.options import config

        # Get the path that would be found
        found_path = str(tmpdir.join(".flake8"))

        # Delete it to simulate race condition  
        tmpdir.join(".flake8").remove()

        # This should NOT raise an exception - auto-discovered files are optional
        cfg, cfg_dir = config.load_config(found_path, [])

        # Should return empty config since file didn't exist when read
        assert cfg.sections() == []
        assert cfg_dir == str(tmpdir)

if __name__ == "__main__":
    # Manual test execution
    import sys
    sys.path.insert(0, "src")

    with tempfile.TemporaryDirectory() as tmpdir:
        class MockTmpDir:
            def __init__(self, path):
                self.path = path

            def join(self, name):
                return MockTmpPath(os.path.join(self.path, name))

            def as_cwd(self):
                class CWD:
                    def __init__(self, path):
                        self.path = path
                        self.old_cwd = None

                    def __enter__(self):
                        self.old_cwd = os.getcwd()
                        os.chdir(self.path)
                        return self

                    def __exit__(self, *args):
                        if self.old_cwd:
                            os.chdir(self.old_cwd)

                return CWD(self.path)

        class MockTmpPath:
            def __init__(self, path):
                self.path = path

            def write(self, content):
                with open(self.path, 'w') as f:
                    f.write(content)

            def remove(self):
                os.remove(self.path)

            def __str__(self):
                return self.path

        mock_tmpdir = MockTmpDir(tmpdir)
        test_load_config_auto_discovered_file_disappears_gracefully(mock_tmpdir)
        print("✓ Test passed!")

